/**
 * The /demo patient, Jane Doe: an invented person. The documents are the cleaned
 * `selection_20` fixtures (15 Polish lab PDFs and 5 phone photos, 2012–2024), served from
 * public/samples/jane-doe. Every name, lab, address and identifier on them is fictional.
 *
 * The readings below were transcribed from those pages and checked by hand, with the
 * outline of each printed row. The demo is prepared data: it never calls a model.
 * Regenerate it together with the page images if the fixtures change.
 */
import type {
  RecordDomain,
  RecordPoint,
  RecordsResponse,
  RecordSeries,
  RecordWarning,
} from '@shared/records';
import type { Flag, Language, Observation, ResultsResponse } from '@shared/results';

export interface DemoPage {
  /** Relative to the base href. */
  src: string;
  width: number;
  height: number;
}
/** One original document, as the patient handed it in. */
export interface DemoDocument {
  id: string;
  /** The file name. */
  name: string;
  /** What the document contains, in its own language. */
  title: string;
  /** Collection date (YYYY-MM-DD); for the cumulative table, its latest column. */
  date: string;
  language: Language;
  kind: 'pdf' | 'image';
  /** Why the document is interesting for the demo, if it is. */
  note: string | null;
  thumb: string;
  pages: DemoPage[];
}

