      'This photo is very blurry and its labels sit a row away from their values, so this number may belong to another test. Check the photo before adding it to a chart.',
    by: 'rules',
    printedName: TO_CHECK[3],
    printedValue: TO_CHECK[4],
    printedUnit: TO_CHECK[5],
